bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true
root="$(mktemp -d)"
trap 'rm -rf "$root"' EXIT
docker cp "$cid":/opt/videobot/src/telegram/paidListingPublisher.mjs "$root/paidListingPublisher.mjs"
test "$(git hash-object "$root/paidListingPublisher.mjs")" = 46520c56ce0ab1940e313a4c15d3d385b06adcef || { echo SOURCE_CHANGED; exit 71; }
python3 - "$root/paidListingPublisher.mjs" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1]);s=p.read_text()
old="""    const paidResult=await telegramApi('sendPaidMedia',paid);
    if (!Number.isSafeInteger(paidResult?.message_id) || paidResult.message_id <= 0)
      throw new Error('paid media acknowledgment invalid');
    await store.recordPaid(key,paidResult.message_id);"""
new="""    const paidResult=await telegramApi('sendPaidMedia',paid);
    // Message IDs are not evidence that Telegram accepted a native Stars lock.
    const nativePaid=paidResult?.paid_media;
    if (!Number.isSafeInteger(paidResult?.message_id) || paidResult.message_id <= 0 ||
        paidResult.chat?.id !== topic.chatId ||
        (paidResult.message_thread_id != null && paidResult.message_thread_id !== topic.threadId) ||
        !nativePaid || nativePaid.star_count !== listing.priceStars ||
        !Array.isArray(nativePaid.paid_media) || nativePaid.paid_media.length !== 1)
      throw new Error('paid media acknowledgment invalid: native Stars lock not confirmed');
    await store.recordPaid(key,paidResult.message_id);"""
if s.count(old)!=1: raise SystemExit('PATCH_ANCHOR_MISMATCH')
p.write_text(s.replace(old,new))
PY
chmod 0644 "$root/paidListingPublisher.mjs"
image="$(docker inspect "$cid" --format '{{.Config.Image}}')"
docker image inspect "$image" >/dev/null
printf 'FROM %s\nCOPY paidListingPublisher.mjs /opt/videobot/src/telegram/paidListingPublisher.mjs\n' "$image" > "$root/Dockerfile"
tag=gace-createvdobot-paidlock-ack-20261123
docker build --quiet -t "$tag" "$root" >/dev/null
docker run --rm --network none --entrypoint node "$tag" --check /opt/videobot/src/telegram/paidListingPublisher.mjs
docker run --rm -i --network none --entrypoint node "$tag" --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { publishVideoListing } from '/opt/videobot/src/telegram/paidListingPublisher.mjs';
const mk=good=>{
 const db=new Map(), calls=[];
 const store={read:async k=>db.get(k),claim:async ({key})=>{db.set(key,{status:'sending'});return {claimed:true}},recordFree:async(k,ids)=>{db.set(k,{status:'sending',freeMessageIds:ids})},recordPaid:async(k,id)=>{db.set(k,{...db.get(k),status:'sent',paidMessageId:id})},markUnknown:async k=>{db.set(k,{...db.get(k),status:'needs_reconcile'})}};
 const listing={id:'sale001',sellerId:'123',revision:1,title:'test',priceStars:10,thumbnail:{fileId:'photo001'},sample:{fileId:'sample001'},paidVideo:{fileId:'paid001'},rightsVerified:true,adultConsentVerified:true,ownerConfirmedPublish:true,feeTermsAccepted:true,managementFeeBps:3000};
 const deps={listing,store,getVerifiedVideoTopic:async()=>({purpose:'video_sale',board:'video_chat',enabled:true,verified:true,chatId:-100123456,threadId:9,title:'video',id:9}),verifyMembership:async()=>true,verifyReview:async()=>true,verifyRelease:async()=>true,telegramApi:async(method,params)=>{calls.push(method);if(method==='sendMediaGroup')return [{message_id:11,media_group_id:'groupX'},{message_id:12,media_group_id:'groupX'}];return good?{message_id:13,chat:{id:-100123456},message_thread_id:9,paid_media:{star_count:10,paid_media:[{type:'video'}]}}:{message_id:13,chat:{id:-100123456},video:{file_id:'paid001'}}}};
 return {deps,db,calls};
};
for(const good of [true,false]){const v=mk(good);if(good){const result=await publishVideoListing(v.deps);assert.equal(result.posted,true);assert.equal(v.db.get('sale001:1').status,'sent')}else{await assert.rejects(()=>publishVideoListing(v.deps),/native Stars lock not confirmed/);assert.equal(v.db.get('sale001:1').status,'needs_reconcile')}assert.deepEqual(v.calls,['sendMediaGroup','sendPaidMedia'])}
console.log('VIDEO_PAID_ACK_GATE_SYNTHETIC_TEST=PASS');
JS
echo "PAIDLOCK_STAGED_IMAGE=$tag"
echo "PAIDLOCK_STAGED_IMAGE_ID=$(docker image inspect "$tag" --format '{{.Id}}')"
echo "BASE_RUNNING_IMAGE=$image"
